package com.bank.crossborder.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDateTime;

@Entity
@Table(name = "cross_border_transfers")
public class CrossBorderTransfer {
    @Id @Column(name = "transfer_id") private String transferId;
    @Column(name = "from_account") private String fromAccount;
    @Column(name = "to_iban") private String toIban;
    private BigDecimal amount;
    private String currency;
    private String status;
    @Column(name = "partner_ref") private String partnerRef;
    @Column(name = "created_at") private LocalDateTime createdAt;

    protected CrossBorderTransfer() {}

    public CrossBorderTransfer(String transferId, String fromAccount, String toIban,
                                BigDecimal amount, String currency) {
        this.transferId = transferId;
        this.fromAccount = fromAccount;
        this.toIban = toIban;
        this.amount = amount;
        this.currency = currency;
        this.status = "INITIATED";
        this.createdAt = LocalDateTime.now();
    }

    public void markPending() { this.status = "PENDING_PARTNER"; }
    public void markCompleted(String ref) { this.status = "COMPLETED"; this.partnerRef = ref; }
    public void markFailed() { this.status = "FAILED"; }

    public String getTransferId() { return transferId; }
    public String getFromAccount() { return fromAccount; }
    public BigDecimal getAmount() { return amount; }
    public String getStatus() { return status; }
}
