// Simulates a SLOW external REST call (2-5 seconds)
package com.bank.crossborder.client;

import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;
import java.math.BigDecimal;
import java.util.UUID;

@Component
@Slf4j
public class PartnerBankClient {

    /**
     * Calls partner bank API over the network.
     * Takes 2-5 SECONDS (network latency + partner processing).
     * During this time, the calling thread is BLOCKED.
     */
    public String creditForeignAccount(String iban, BigDecimal amount, String currency) {
        log.info("[PARTNER] Calling partner bank API: credit {} {} to {}", amount, currency, iban);
        try {
            Thread.sleep(3000);  // simulate 3-second network call
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        String ref = "PTNR-" + UUID.randomUUID().toString().substring(0, 6);
        log.info("[PARTNER] Partner confirmed: ref={}", ref);
        return ref;
    }
}
