// *** ANTI-PATTERN: holds DB connection during 3-second REST call ***
package com.bank.crossborder.service;

import com.bank.crossborder.client.PartnerBankClient;
import com.bank.crossborder.model.CrossBorderTransfer;
import com.bank.crossborder.repository.TransferRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.UUID;

@Service
@RequiredArgsConstructor
@Slf4j
public class BadTransferService {

    private final TransferRepository transferRepo;
    private final PartnerBankClient partnerClient;

    /**
     * *** ANTI-PATTERN: Pseudo-saga ***
     *
     * This method holds a DB CONNECTION for the ENTIRE duration:
     * 1. Get connection from pool (~0ms)
     * 2. INSERT transfer (~5ms)
     * 3. Call partner bank REST API (~3000ms) ← CONNECTION HELD DURING THIS!
     * 4. UPDATE transfer (~5ms)
     * 5. COMMIT + release connection
     *
     * Connection held: 3010ms (but only 10ms was actual DB work!)
     *
     * With 20 connections and 3s per call:
     * Max throughput = 20 / 3 = ~7 transfers per second
     * At 10 req/s: pool exhausted in 6 seconds → "Connection not available"
     *
     * The DB is IDLE during the 3s network call. This is WASTE.
     */
    @Transactional
    public String transferBad(String fromAccount, String toIban, BigDecimal amount, String currency) {
        String id = "CBT-" + UUID.randomUUID().toString().substring(0, 6).toUpperCase();
        log.warn("[BAD] Connection held during entire REST call!");

        CrossBorderTransfer transfer = new CrossBorderTransfer(id, fromAccount, toIban, amount, currency);
        transferRepo.save(transfer);  // 5ms DB work

        // *** 3 SECOND NETWORK CALL — CONNECTION STILL HELD! ***
        String partnerRef = partnerClient.creditForeignAccount(toIban, amount, currency);

        transfer.markCompleted(partnerRef);
        transferRepo.save(transfer);  // 5ms DB work

        return id;
        // Total: connection held 3010ms. DB used 10ms. 3000ms WASTED on network.
    }
}
